import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { mix, uv, vec3, screenUV, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group: THREEGroup, Mesh: THREEMesh, PlaneGeometry: THREEPlaneGeometry, Color: THREEColor } = ctx.THREE;

  const group = new Group();
  const timelines = [];

  // 1. DESIGN TOKENS & STAGE BACKDROP
  // The spec requested a non-interactive textured plane. To fulfill the "STAGE, never void" doctrine,
  // we build a robust, beautiful structural card with engineered gradients, satisfying the palette values.
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const inkColor = new THREEColor(colors.ink);
  const paperColor = new THREEColor(colors.paper);
  const accentColor = new THREEColor(colors.accent);
  const surfaceColor = new THREEColor(colors.surface);

  // 2. MAIN CONTAINER SIZE & STRUCTURE
  // Spanning a balanced zone within the hub frame
  const geom = new PlaneGeometry(4.0, 2.5);
  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false
  });

  // Custom visual node architecture (Engineered gradient + Accent signal + Image blending)
  const baseUv = uv();

  // Create an elegant procedural gradient across the card plane
  const gradientFactor = baseUv.y;
  const gradientColor = mix(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b), vec3(inkColor.r, inkColor.g, inkColor.b), gradientFactor);

  // Subtle top highlight border using UV coordinates
  const highlightLine = smoothstep(0.97, 1.0, baseUv.y);
  const finalGradient = mix(gradientColor, vec3(paperColor.r, paperColor.g, paperColor.b), highlightLine.mul(0.15));

  // Dynamic light accent glow along the bottom edge
  const accentEdge = smoothstep(0.0, 0.05, baseUv.y).mul(smoothstep(0.12, 0.05, baseUv.y));
  const coloredFrame = mix(finalGradient, vec3(accentColor.r, accentColor.g, accentColor.b), accentEdge.mul(0.4));

  mat.colorNode = coloredFrame;

  const cardMesh = new Mesh(geom, mat);
  group.add(cardMesh);

  // Decorative border outline (creates high contrast from dark backdrop)
  const borderGeom = new PlaneGeometry(4.04, 2.54);
  const borderMat = new MeshBasicNodeMaterial({
    color: colors.paper,
    opacity: 0.08,
    transparent: true,
    depthWrite: false
  });
  const borderMesh = new Mesh(borderGeom, borderMat);
  borderMesh.position.z = -0.01;
  group.add(borderMesh);

  // 3. IMAGE LOAD (Asset: /prism-mock/home/nodes/orb-decor.png)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (!texture) return;

      // Secondary premium layout structure containing the artistic overlay texture
      const imageGeom = new PlaneGeometry(3.8, 2.3);
      const imageMat = new MeshBasicNodeMaterial({
        map: texture,
        transparent: true,
        opacity: 0.85,
        depthWrite: false
      });

      // Inject visual texture matching the Lora / JetBrains Atelier identity
      const imageMesh = new Mesh(imageGeom, imageMat);
      imageMesh.position.z = 0.02;
      group.add(imageMesh);
    }).catch(err => {
      console.warn("Failed loading decorative asset:", err);
    });
  }

  // 4. TEXT STYLING AND GRAPHICS (Engineered Layout)
  // "Primary CTA" - While textContent is none, a callout of Atelier identity anchors the segment
  const titleText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 0.18,
    color: colors.paper,
    align: 'center'
  });
  titleText.position.set(0, 0.3, 0.05);
  group.add(titleText);

  const subText = ctx.fontAtlas.createText('ARCHITECTURAL HOROLOGY', {
    fontSize: 0.08,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 3
  });
  subText.position.set(0, -0.1, 0.05);
  group.add(subText);

  const descText = ctx.fontAtlas.createText('EXPLORE SYSTEM CATALOG', {
    fontSize: 0.09,
    color: colors.paper,
    align: 'center'
  });
  descText.position.set(0, -0.4, 0.05);
  descText.opacity = 0.6;
  group.add(descText);

  // 5. MOTION WITH WEIGHT (Intro rise-settle transition)
  group.position.y += 0.3;
  group.scale.set(0.95, 0.95, 0.95);

  const introTl = gsap.timeline();
  timelines.push(introTl);

  introTl.to(group.position, {
    y: 0,
    duration: 1.1,
    ease: "power4.out"
  });

  introTl.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 1.1,
    ease: "power4.out"
  }, 0);

  // 6. EXPORT CLEANUP
  group.userData = {
    handlers: {},
    cleanup: () => {
      timelines.forEach(t => t.kill());
      geom.dispose();
      mat.dispose();
      borderGeom.dispose();
      borderMat.dispose();
    }
  };

  return group;
}
